import {arrivalContent as arrivalText} from './story-arrivals-content.mjs';
import {actTwoView} from './act-two-core.mjs';
import {actTwoInvitation} from './act-two-ui.mjs';
import {keeperStoryContent as content,keeperPageAmounts} from './keeper-story-content.mjs';
import {storyView,keepParcel,revealOldMap,setPageAmount} from './keeper-story-core.mjs';
import {guides} from './companions.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const guide=state=>guides.find(g=>g.id===state.garden?.guide)||guides[0];
const named=(text,state)=>String(text).replaceAll('{guide}',guide(state).name);
const paragraphs=(lines,state)=>lines.map(p=>`<p>${esc(named(p,state))}</p>`).join('');
const speak=lines=>lines.join(' ').replaceAll('[smudged word]','a smudged word');
const button=(attr,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(label)}</button>`;
const blockedAttr=blocked=>blocked?' hidden':'';
function parcelArt(){return `<svg class="keeper-parcel-art" viewBox="0 0 320 175" role="img" aria-label="A wet paper parcel tied with string, beside a flowerpot. Its label is smudged."><path d="M12 160Q148 145 307 161" stroke="#78b7cf" stroke-width="9" fill="none"/><path d="M30 87H97L88 155H42Z" fill="#b99b73" stroke="#203f58" stroke-width="3"/><path d="M62 88V32M62 54Q27 32 31 14Q66 16 62 54M64 69Q94 40 109 43Q110 78 64 69" fill="#6b8b61" stroke="#496b4d" stroke-width="3"/><path d="M118 71L249 48 288 126 153 153Z" fill="#c8ad7b" stroke="#203f58" stroke-width="3"/><path d="M119 72L153 153M177 61L218 141M132 109L266 87" stroke="#fffdf6" stroke-width="5"/><path d="M193 79l46-8 16 29-48 9Z" fill="#fffdf6" stroke="#203f58" stroke-width="2"/><path d="M208 89l20-4m-16 12 22-4" stroke="#8b9a9d" stroke-width="4"/><path d="M267 23l-4 13m24 5-6 12m-142-24-4 13" stroke="#78b7cf" stroke-width="4" stroke-linecap="round"/></svg>`;}
function parcelScene(state,v,{almanac=false}={}){const lines=v.opening==='fresh'?content.parcel.fresh:content.parcel.returning;return `<section class="keeper-parcel-scene" data-keeper-intro><div class="keeper-scene-heading">${parcelArt()}<h2 data-keeper-heading tabindex="-1">${esc(content.parcel.title)}</h2></div>${paragraphs(lines,state)}<div class="keeper-controls">${button('data-keeper-keep',content.parcel.keepLabel,true)}${hearButton(speak(lines.map(x=>named(x,state))),'Hear the parcel story','en')}${!almanac?'<a class="text-button" href="#almanac">Visit the Keeper’s Pages</a>':''}</div></section>`;}
function reminder(state,v){const lines=v.opening==='fresh'?content.parcel.fresh:content.parcel.returning;return `<section data-keeper-reminder tabindex="-1"><h2 data-keeper-heading tabindex="-1">${esc(content.ui.reminderTitle)}</h2><p>${esc(content.parcel.after)}</p><p>${esc(content.parcel.reminder)}</p><details class="keeper-replay"><summary>${esc(content.parcel.replayLabel)}</summary>${paragraphs(lines,state)}${hearButton(speak(lines.map(x=>named(x,state))),'Hear the parcel story again','en')}</details></section>`;}
function stuck(){return `<section class="keeper-drying"><div class="keeper-paper-edge" role="img" aria-label="${esc(content.page.stuckAlt)}"><span>Sponge</span></div><div><h2 data-keeper-heading tabindex="-1">${esc(content.page.drying)}</h2><a class="secondary" href="#cafe">Visit the café</a></div></section>`;}
export function keeperInvitation(state,{blocked=false}={}){const inherited=storyView(state);if(inherited.inheritedPageOne&&!inherited.pageVisible)return `<section class="keeper-invitation" data-keeper-story data-keeper-invite lang="en"${blockedAttr(blocked)}><h2 data-keeper-heading tabindex="-1">${esc(arrivalText.context.before)}</h2><p>${esc(arrivalText.context.inheritedMap)}</p><a class="primary" href="#almanac/keepers">${esc(content.page.revealLabel)}</a></section>`;const town=actTwoInvitation(state,{blocked});if(town)return town;const v=storyView(state);if(!v.eligible||v.status==='unavailable')return '';const text=v.oldMapRevealed?content.invitation.reread:v.parcelFound?content.invitation.found:content.invitation.unfound;return `<section class="keeper-invitation" data-keeper-story data-keeper-invite lang="en"${blockedAttr(blocked)}><div><h2 data-keeper-heading tabindex="-1">${esc(text.title)}</h2><p>${esc(text.body)}</p></div><a class="primary" href="#almanac/keepers">${esc(v.oldMapRevealed?'Read the old map again':content.invitation.button)}</a><p class="keeper-status" role="status" aria-live="polite" tabindex="-1"></p></section>`;}
export function parcelHome(state,{blocked=false}={}){const v=storyView(state);if(v.status==='unavailable')return `<aside class="keeper-return"><a href="#almanac">Your earlier Keeper’s Pages are kept safe</a></aside>`;if(v.inheritedPageOne)return `<div class="keeper-home" data-keeper-root data-keeper-story lang="en"${blockedAttr(blocked)}><h2 data-keeper-heading tabindex="-1" data-arrival-context>${esc(arrivalText.context.before)}</h2><p>${esc(arrivalText.context.earlierPages)}</p><div class="keeper-controls"><a class="secondary" href="#almanac/keepers">${esc(content.page.revealLabel)}</a>${v.inheritedPageTwo?'<a class="secondary" href="#almanac/flood-ledger">Read the flood ledger</a><a class="secondary" href="#almanac/upstream-letter">Open the upstream letter</a>':''}</div>${v.pageVisible?actTwoInvitation(state):''}<p class="keeper-status" role="status" aria-live="polite" tabindex="-1"></p></div>`;return `<div class="keeper-home" data-keeper-root data-keeper-story lang="en"${blockedAttr(blocked)}>${!v.parcelFound?parcelScene(state,v):`${reminder(state,v)}<a class="secondary" href="#almanac">${esc(content.title)}</a>${keeperInvitation(state)}`}<p class="keeper-status" role="status" aria-live="polite" tabindex="-1"></p></div>`;}
function mapArt(){return `<figure class="keeper-valley-map"><svg viewBox="0 0 700 430" role="img" aria-label="Fictional old valley sketch: Willow Brook loops through the Sponge, a marsh marked with reeds, from the high ford toward the mill. The bridge road follows drier ground. Not to scale."><rect x="4" y="4" width="692" height="422" rx="24" fill="#f2e9cb" stroke="#b99b73" stroke-width="3"/><path d="M40 50Q103 10 177 53M547 48Q615 11 665 54M565 377Q622 342 667 380" fill="none" stroke="#acb899" stroke-width="10"/><path d="M182 115Q293 58 424 123T529 278Q435 340 279 287T168 188Z" fill="#bfd2a3" stroke="#6b8b61" stroke-width="3"/><path d="M87 22Q131 98 246 128T321 191Q205 218 275 257T443 272Q490 337 606 405" fill="none" stroke="#78b7cf" stroke-width="21"/><path d="M107 21Q153 86 270 116T346 191Q240 218 298 254T459 263Q514 329 622 405" fill="none" stroke="#4f8da8" stroke-width="2"/><path d="M80 85Q157 122 143 229T236 387L534 382" stroke="#b99b73" stroke-width="10" stroke-dasharray="15 8" fill="none"/><path d="M126 105l25 35M129 102l25 34" stroke="#665540" stroke-width="5"/><path d="M488 323h68v57h-68Z" fill="#fffdf6" stroke="#203f58" stroke-width="3"/><path d="M478 323l44-27 46 27Z" fill="#b99b73" stroke="#203f58" stroke-width="3"/><circle cx="480" cy="361" r="21" fill="#d9c99d" stroke="#203f58" stroke-width="3"/><path d="M480 340v42m-21-21h42" stroke="#203f58" stroke-width="2"/>${[[207,153],[432,155],[203,242],[376,284],[482,235]].map(([x,y])=>`<path d="M${x} ${y}v-25m0 13-8-8m8 3 8-8" stroke="#496b4d" stroke-width="3" fill="none"/>`).join('')}<g fill="#203f58" font-family="sans-serif" font-size="22"><text x="54" y="76">High ford</text><text x="215" y="85">Willow Brook</text><text x="282" y="163">The Sponge</text><text x="34" y="290">Bridge road</text><text x="571" y="348">Mill</text></g><g data-keeper-orchard-art hidden><path d="M189 113Q286 75 424 128T508 269Q417 328 279 282T173 182Z" fill="none" stroke="#8a5223" stroke-width="5" stroke-dasharray="9 6"/><g fill="#8a5223">${[[250,200],[365,219],[415,180],[330,270]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="11"/><path d="M${x} ${y+11}v15" stroke="#8a5223" stroke-width="3"/>`).join('')}</g></g></svg><figcaption>${esc(content.page.mapLegend)} Places shown: high ford, mill and bridge road. <strong data-keeper-overlay-label hidden>${esc(content.page.overlayLabel)}.</strong> ${esc(content.page.mapLimit)}</figcaption></figure>`;}
function pageReading(state,v){const amount=content.page.amounts[v.pageAmount]||content.page.amounts.short,lines=amount.paragraphs;return `<article class="keeper-map-page"><h2 data-keeper-heading tabindex="-1">${esc(content.page.title)}</h2><p>${esc(content.label)}. ${esc(actTwoView(state).pageReady?arrivalText.context.twoPages:content.page.dryLine)}</p><div class="keeper-controls" role="group" aria-label="Page reading amount">${keeperPageAmounts.map(key=>button(`data-keeper-amount="${key}" aria-pressed="${key===v.pageAmount}"`,content.page.amounts[key].label,key===v.pageAmount)).join('')}</div><div class="keeper-page-words" data-keeper-reading tabindex="-1">${paragraphs(lines,state)}</div>${hearButton(speak(lines),'Hear this version','en')}${mapArt()}<div class="keeper-controls">${button('data-keeper-overlay aria-pressed="false"',content.ui.orchardToggle)}</div><div class="keeper-glossary" role="group" aria-label="Words on the page">${Object.entries(content.glossary).map(([key,value])=>`<details><summary>${esc(key)}</summary><p>${esc(value)}</p>${hearButton(`${key}: ${value}`,`Hear ${key}`,'en')}</details>`).join('')}</div><p class="keeper-guide">${esc(named(content.page.guideLine,state))}</p><details class="keeper-replay"><summary>${esc(content.ui.revealReplayTitle)}</summary>${paragraphs(content.page.reveal,state)}${hearButton(speak(content.page.reveal),'Hear how the page came free','en')}</details><p><a class="secondary" href="#desk">Visit the Keeper’s Desk</a></p><p>One town question is open there: Bridge or ford?</p><p><a class="secondary" href="#workshop/old-map">Read the old map as an editor</a></p></article>`;}
export function keeperPages(state,{blocked=false}={}){const v=storyView(state);let body;
 if(v.status==='unavailable')body=`<section><h2 data-keeper-heading tabindex="-1">${esc(content.ui.recoveryTitle)}</h2><p>${esc(content.ui.recoveryBody)}</p><a class="secondary" href="#notes">Open Grown-up notes</a><details><summary>${esc(content.ui.recoveryReplay)}</summary>${paragraphs(content.parcel.returning,state)}</details></section>`;
 else if(v.inheritedPageOne&&!v.pageVisible)body=`<section data-arrival-context><h2 data-keeper-heading tabindex="-1">${esc(arrivalText.context.before)}</h2><p>${esc(arrivalText.context.inheritedMap)}</p><div class="keeper-controls">${button('data-keeper-reveal',content.page.revealLabel,true)}${hearButton(arrivalText.context.inheritedMap,'Hear about the earlier page','en')}</div></section>`;
 else if(!v.parcelFound&&!v.inheritedPageOne)body=parcelScene(state,v,{almanac:true});
 else if(!v.eligible&&!v.inheritedPageOne)body=`${reminder(state,v)}${stuck()}`;
 else if(!v.oldMapRevealed)body=`<section class="keeper-reveal"><h2 data-keeper-heading tabindex="-1">${esc(content.ui.revealTitle)}</h2>${paragraphs(content.page.reveal,state)}<div class="keeper-controls">${button('data-keeper-reveal',content.page.revealLabel,true)}${hearButton(speak(content.page.reveal),'Hear Dot’s discovery','en')}</div></section>`;
 else body=`${v.inheritedPageOne?`<aside data-arrival-context><h2>${esc(arrivalText.context.before)}</h2><p>${esc(arrivalText.context.earlierPages)}</p></aside>`:''}`+pageReading(state,v)+actTwoInvitation(state);
 return `<div class="keeper-pages" data-keeper-root data-keeper-story lang="en"${blockedAttr(blocked)}><header><a class="back" href="#home">Back to the garden</a><h1 tabindex="-1" id="keeper-pages-title">${esc(content.title)}</h1><p>${esc(content.label)}. Read together, listen, or look closely.</p></header>${body}<p class="keeper-status" role="status" aria-live="polite" tabindex="-1"></p><nav class="keeper-controls" aria-label="Other places"><a class="secondary" href="#cafe">Visit the café</a><a class="secondary" href="#explore">Choose another place</a></nav></div>`;
}
export function keeperNotes(state){const v=storyView(state);if(v.status==='missing')return '';return `<details class="panel"><summary>The Keeper’s Pages · story record</summary><p>Scenes and story milestones are separate from learning observations. Reading a page, choosing an amount or watching a film records no proficiency.</p>${v.status==='ready'?`<p>Parcel kept by this explorer: ${v.parcelFound?'yes':'not yet'}. Actual first supper ending kept: ${v.ended?'yes':'not yet'}. Old map read: ${v.oldMapRevealed?'yes':'not yet'}.</p>${v.actIStatus==='unreadable'?'<p>The earlier Act I entry is unreadable here and remains unchanged. Other story parts can continue.</p>':''}${v.receiptStatus==='unreadable'?'<p>Earlier receipt details remain raw; the kept ending is retained.</p>':''}`:'<p>The earlier story format is preserved unchanged.</p>'}<details><summary>Stored story IDs and milestone receipt</summary><pre>${esc(JSON.stringify(state.story,null,2))}</pre></details></details>`;}
export function refreshKeeperVisibility(blocked=!!document.querySelector('dialog.welcome-film[open]')){document.querySelectorAll('[data-keeper-story]').forEach(el=>{el.hidden=blocked;});}
export function bindKeeperStory(state,{save,render,focus,canExport,explorerId,isActive}){const owner=explorerId?.(),roots=[...document.querySelectorAll('[data-keeper-root]')];for(const root of roots){
 const route=window.location.hash;
 const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&window.location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner&&!document.querySelector('dialog.welcome-film[open]');
 const status=message=>{const s=root.querySelector('.keeper-status');if(s){s.textContent=message;s.focus();}};
 const options={canExport},failed='This story change could not be kept safely. Your earlier work is unchanged. You can download your notes and keep exploring.';
 const redraw=(message,target)=>{stopSpeech();save();render();const s=document.querySelector('.keeper-status');if(s)s.textContent=message;focus?.(target||'[data-keeper-heading]');};
 const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 bind('[data-keeper-keep]',()=>{if(!keepParcel(state,options))return status(failed);redraw(content.parcel.after,root.classList.contains('keeper-home')?'[data-keeper-reminder]':'#keeper-pages-title');});
 bind('[data-keeper-reveal]',()=>{if(!revealOldMap(state,options))return status(failed);redraw('The old map is kept in the Keeper’s Pages. You can read it again.','[data-keeper-reading]');});
 bind('[data-keeper-amount]',b=>{if(!setPageAmount(state,b.dataset.keeperAmount,options))return status(failed);redraw('Reading amount changed for this page only.',`[data-keeper-amount="${b.dataset.keeperAmount}"]`);});
 bind('[data-keeper-overlay]',b=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));root.querySelectorAll('[data-keeper-orchard-art],[data-keeper-overlay-label]').forEach(el=>{el.toggleAttribute('hidden',!on);});});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true}));
}}
